#!/usr/bin/env python3
"""G5 scratch Lake package sources (core-only Lean; throwaway measurement, D77: never library code).

Kept as strings, not as .lean files in the repository (as the generated probes of kernel-tests/Packed): the
native block files use native_decide, and none of this is a KAM module.  usage: g5_sources.py OUTDIR
"""
import os, sys

FILES = {
    'G5/Mirror.lean': "/-\nG5 (SJSU-FULL gates): a core-only mirror of the computational part of the landed packed real product\n`KAM.CertificateSharp.Packed.gmpRealProduct` (commit 7cdc184ee; unchanged on main at 8b8611000), without the\nℚ remainder.  Every definition below is copied from the library source named in its comment, with the\nlibrary's proofs dropped; no Mathlib, no KAM import.  Throwaway measurement code (D77: native_decide never\nenters tracked library code); it is not part of the KAM library.\n-/\n\nnamespace G5\n\n/-- `KAM.Certificate.CertKey` (Poly/Basic.lean). -/\nabbrev CertKey : Type := List Int\n\n/-- Poly/Layout.lean. -/\ndef packDot (u s : List Nat) : Nat := (List.zipWith (· * ·) u s).sum\n\n/-- Poly/Layout.lean. -/\ndef packDigits : List Nat → Nat → List Nat\n  | [], _ => []\n  | s :: ss, i => i / s :: packDigits ss (i % s)\n\n/-- Poly/Layout.lean. -/\ndef packNoWrap : List Nat → List Nat → Bool\n  | [], [] => true\n  | [s], [_] => decide (1 ≤ s)\n  | s :: s' :: ss, _ :: e' :: es => decide (s' * e' ≤ s) && packNoWrap (s' :: ss) (e' :: es)\n  | _, _ => false\n\n/-- Poly/Layout.lean. -/\nstructure PackLayout where\n  lo : CertKey\n  dims : List Nat\n  stride : List Nat\n  width : Nat\n  blockRows : Nat\n\n/-- Poly/Layout.lean. -/\ndef PackLayout.denseLen (L : PackLayout) : Nat :=\n  if L.dims.all fun d => decide (0 < d) then 1 + packDot (L.dims.map (· - 1)) L.stride else 0\n\n/-- Poly/Layout.lean. -/\ndef packSlotAux : List Int → List Int → List Nat → List Nat → Option Nat\n  | [], _, [], _ => some 0\n  | x :: xs, lo, d :: ds, ss =>\n    match x - lo.headD 0 with\n    | Int.ofNat u => if u < d then (packSlotAux xs lo.tail ds ss.tail).map (u * ss.headD 0 + ·)\n        else none\n    | Int.negSucc _ => none\n  | _, _, _, _ => none\n\n/-- Poly/Layout.lean. -/\ndef packStrictAsc : List (Nat × Int) → Bool\n  | a :: b :: rest => decide (a.1 < b.1) && packStrictAsc (b :: rest)\n  | _ => true\n\n/-- Poly/Layout.lean. -/\ndef PackLayout.prodKey (La Lb : PackLayout) (i : Nat) : CertKey :=\n  (List.range La.dims.length).map fun j =>\n    La.lo.getD j 0 + Lb.lo.getD j 0 + ((packDigits La.stride i).getD j 0 : Int)\n\n/-- Poly/Layout.lean. -/\ndef PackLayout.compat (n : Nat) (La Lb : PackLayout) : Bool :=\n  La.dims.length == n && Lb.dims.length == n && La.stride.length == n &&\n    La.stride == Lb.stride && La.width == Lb.width &&\n    packNoWrap La.stride (List.zipWith (fun a b => a + b - 1) La.dims Lb.dims)\n\n/-- Poly/MulPacked.lean. -/\ndef PackLayout.slotTerms (L : PackLayout) (cs : List (CertKey × Int)) : List (Nat × Int) :=\n  cs.map fun t => ((packSlotAux t.1 L.lo L.dims L.stride).getD 0, t.2)\n\n/-- Poly/MulPacked.lean. -/\ndef PackLayout.allSlots (L : PackLayout) (cs : List (CertKey × Int)) : Bool :=\n  cs.all fun t => (packSlotAux t.1 L.lo L.dims L.stride).isSome\n\n/-- Poly/Advice.lean. -/\ndef packMaxAbsAux : Nat → List Int → Nat\n  | m, [] => m\n  | m, c :: cs => if m < c.natAbs then packMaxAbsAux c.natAbs cs else packMaxAbsAux m cs\n\n/-! Poly/Sparse.lean: balanced sparse packing. -/\n\ndef spLeaf (e : Nat × Int) : Nat × Nat × Nat :=\n  if 0 ≤ e.2 then (e.1, e.2.toNat, 0) else (e.1, 0, (-e.2).toNat)\n\ndef spJoin (w : Nat) (x y : Nat × Nat × Nat) : Nat × Nat × Nat :=\n  if x.1 ≤ y.1 then\n    (x.1, x.2.1 + (y.2.1 <<< (w * (y.1 - x.1))), x.2.2 + (y.2.2 <<< (w * (y.1 - x.1))))\n  else (y.1, y.2.1 + (x.2.1 <<< (w * (x.1 - y.1))), y.2.2 + (x.2.2 <<< (w * (x.1 - y.1))))\n\ndef spLevel (w : Nat) : List (Nat × Nat × Nat) → List (Nat × Nat × Nat)\n  | x :: y :: r => spJoin w x y :: spLevel w r\n  | r => r\n\ndef spFold (w : Nat) : List (Nat × Nat × Nat) → Nat × Nat × Nat\n  | [] => (0, 0, 0)\n  | [x] => x\n  | x :: y :: r => spJoin w x (spFold w (y :: r))\n\ndef spTree (w : Nat) : Nat → List (Nat × Nat × Nat) → Nat × Nat × Nat\n  | _, [] => (0, 0, 0)\n  | _, [x] => x\n  | 0, x :: y :: r => spFold w (x :: y :: r)\n  | f + 1, x :: y :: r => spTree w f (spLevel w (x :: y :: r))\n\ndef spPack (w base : Nat) (es : List (Nat × Int)) : Int :=\n  let r := spTree w 64 (es.map spLeaf)\n  ((r.2.1 <<< (w * (r.1 - base)) : Nat) : Int) - ((r.2.2 <<< (w * (r.1 - base)) : Nat) : Int)\n\ndef spMax (es : List (Nat × Int)) : Nat := packMaxAbsAux 0 (es.map Prod.snd)\n\n/-! Packed/Digits.lean, Packed/Round.lean. -/\n\ndef periodic (w N m : Nat) : Nat := m * ((2 ^ (w * N) - 1) / (2 ^ w - 1))\n\ndef digitShift (w N s Y : Nat) : Nat := (Y - (Y &&& periodic w N (2 ^ s - 1))) >>> s\n\ndef gmpRound (w N l s : Nat) (Z : Int) : Int :=\n  (digitShift w N s (Z + (periodic w N (2 ^ l + 2 ^ (s - 1)) : Int)).toNat : Int) -\n    (periodic w N (2 ^ (l - s)) : Int)\n\ndef natJoin (k a b : Nat) : Nat := a + (b <<< k)\n\ndef natRamp (b n : Nat) : Nat :=\n  (n * 2 ^ (b * (n + 1)) + 1 - (n + 1) * 2 ^ (b * n)) / (2 ^ b - 1) ^ 2\n\ndef natDigitsLin (w : Nat) : Nat → Nat → List Nat\n  | 0, _ => []\n  | N + 1, Y => (Y &&& (2 ^ w - 1)) :: natDigitsLin w N (Y >>> w)\n\ndef natDigitsSh (w : Nat) : Nat → Nat → Nat → List Nat\n  | 0, N, Y => natDigitsLin w N Y\n  | f + 1, N, Y =>\n    if N ≤ 16 then natDigitsLin w N Y else\n      natDigitsSh w f (N / 2) (Y &&& (2 ^ (w * (N / 2)) - 1)) ++\n        natDigitsSh w f (N - N / 2) (Y >>> (w * (N / 2)))\n\ndef unpackSlots (w N : Nat) (Z : Int) : List Int :=\n  (natDigitsSh w 64 N (Z + (periodic w N (2 ^ (w - 1)) : Int)).toNat).map\n    fun e : Nat => (e : Int) - 2 ^ (w - 1)\n\n/-! Packed/Product.lean (without the ℚ remainder `GmpSpec.rem`). -/\n\ndef packOf (L : PackLayout) (x : List (CertKey × Int)) : Int := spPack L.width 0 (L.slotTerms x)\n\ndef packRepOk (L : PackLayout) (x : List (CertKey × Int)) (B : Nat) : Bool :=\n  L.allSlots x && packStrictAsc (L.slotTerms x) &&\n    ((L.slotTerms x).all fun e => decide (e.1 < L.denseLen)) && decide (spMax (L.slotTerms x) ≤ B)\n\nstructure GmpSpec where\n  la : PackLayout\n  lb : PackLayout\n  ba : Nat\n  bb : Nat\n  l : Nat\n  s : Nat\n\ndef GmpSpec.prodLen (g : GmpSpec) : Nat := g.la.denseLen + g.lb.denseLen - 1\n\ndef GmpSpec.guard (g : GmpSpec) : Bool :=\n  PackLayout.compat g.la.dims.length g.la g.lb && decide (0 < g.la.denseLen) &&\n    decide (0 < g.lb.denseLen) && (g.la.stride.all fun s => decide (0 < s)) &&\n    decide (min g.la.denseLen g.lb.denseLen * g.ba * g.bb ≤ 2 ^ g.l) &&\n    decide (1 ≤ g.s) && decide (g.s ≤ g.l) && decide (g.l + 2 ≤ g.la.width)\n\ndef GmpSpec.round (g : GmpSpec) (Za Zb : Int) : Int :=\n  gmpRound g.la.width g.prodLen g.l g.s (Za * Zb)\n\ndef gmpEntry (la lb : PackLayout) (ic : Nat × Int) : Option (CertKey × Int) :=\n  if ic.2 = 0 then none else some (la.prodKey lb ic.1, ic.2)\n\ndef GmpSpec.terms (g : GmpSpec) (R : Int) : List (CertKey × Int) :=\n  ((List.range g.prodLen).zip (unpackSlots g.la.width g.prodLen R)).filterMap (gmpEntry g.la g.lb)\n\n/-- The `some` branch of `gmpRealProduct` (non-empty factors), as a Boolean check against the claimed\nread-back terms `T`: guard, both boundary checks, one packed multiplication, advice-free rounding and the\nread-back. -/\ndef gmpCheck (g : GmpSpec) (x y T : List (CertKey × Int)) : Bool :=\n  g.guard && packRepOk g.la x g.ba && packRepOk g.lb y g.bb &&\n    g.terms (g.round (packOf g.la x) (packOf g.lb y)) == T\n\n/-- Zigzag decoding (gate_gen.py's literal format). -/\ndef dz (n : Nat) : Int := if n % 2 = 0 then Int.ofNat (n / 2) else Int.negSucc (n / 2)\n\n/-- A zigzag-coded term with a two-variable key. -/\nabbrev tk (k₀ k₁ v : Nat) : CertKey × Int := ([dz k₀, dz k₁], dz v)\n\nend G5\n",
    'Main.lean': '/-\nG5 compiled checker: runs `G5.gmpCheck` (G5/Mirror.lean) on every block of blocks.txt in compiled code and\nprints, per block, the result and the best of three wall times of the check alone (parsing excluded).\nusage: g5check blocks.txt\n-/\nimport G5.Mirror\n\nopen G5\n\ndef ints (s : String) : List Int := (s.splitOn " ").filterMap String.toInt?\n\ndef layoutOf (s : String) : PackLayout :=\n  match ints s with\n  | [lo0, lo1, d0, d1, s0, s1, w] => ⟨[lo0, lo1], [d0.toNat, d1.toNat], [s0.toNat, s1.toNat], w.toNat, 1⟩\n  | _ => ⟨[], [], [], 0, 0⟩\n\ndef termsOf (ls : Array String) (i n : Nat) : List (CertKey × Int) :=\n  (List.range n).map fun j =>\n    match ints ls[i + j]! with\n    | [a, b, v] => ([a, b], v)\n    | _ => ([], 0)\n\ndef count (s : String) : Nat := (((s.splitOn " ").getD 1 "0").toNat?).getD 0\n\npartial def loop (ls : Array String) (i : Nat) (acc : Nat) (allOk : Bool) : IO (Nat × Bool) := do\n  let h := ls[i]!\n  if h.startsWith "E" then return (acc, allOk)\n  let name := (h.splitOn " ").getD 1 "?"\n  let la := layoutOf ((ls[i + 1]!).drop 2).toString\n  let lb := layoutOf ((ls[i + 2]!).drop 2).toString\n  let g : GmpSpec := match ints ((ls[i + 3]!).drop 2).toString with\n    | [ba, bb, l, s] => ⟨la, lb, ba.toNat, bb.toNat, l.toNat, s.toNat⟩\n    | _ => ⟨la, lb, 0, 0, 0, 0⟩\n  let nx := count ls[i + 4]!\n  let x ← IO.lazyPure fun _ => termsOf ls (i + 5) nx\n  let j := i + 5 + nx\n  let ny := count ls[j]!\n  let y ← IO.lazyPure fun _ => termsOf ls (j + 1) ny\n  let k := j + 1 + ny\n  let nt := count ls[k]!\n  let T ← IO.lazyPure fun _ => termsOf ls (k + 1) nt\n  IO.println s!"parsed {name}: {x.length} {y.length} {T.length}"\n  let mut best : Nat := 0\n  let mut ok := true\n  for r in [0, 1, 2] do\n    let t0 ← IO.monoNanosNow\n    let b ← IO.lazyPure fun _ => gmpCheck g x y T\n    let t1 ← IO.monoNanosNow\n    ok := ok && b\n    if r == 0 || t1 - t0 < best then best := t1 - t0\n  IO.println s!"block {name} ok={ok} best_ns={best}"\n  loop ls (k + 1 + nt) (acc + best) (allOk && ok)\n\ndef main (args : List String) : IO UInt32 := do\n  let ls := (← IO.FS.lines (args.headD "blocks.txt"))\n  let (tot, ok) ← loop ls 0 0 true\n  IO.println s!"TOTAL ok={ok} sum_best_ns={tot}"\n  return (if ok then 0 else 1)\n',
    'lakefile.lean': 'import Lake\nopen Lake DSL\n\n/-- G5 scratch package (SJSU-FULL gates): core Lean only, no Mathlib, no KAM. Throwaway measurement. -/\npackage g5\n\n@[default_target]\nlean_lib G5 where\n  roots := #[`G5.Mirror]\n\n@[default_target]\nlean_exe g5check where\n  root := `Main\n',
    'lean-toolchain': 'leanprover/lean4:v4.35.0\n',
}


def write(d):
    for k, v in FILES.items():
        os.makedirs(os.path.dirname(os.path.join(d, k)) or d, exist_ok=True)
        open(os.path.join(d, k), 'w').write(v)


if __name__ == '__main__':
    write(sys.argv[1])
